
import React, { useState } from 'react';

const IMAGES = [
  'https://images.unsplash.com/photo-1547407139-3c921a66005c?auto=format&fit=crop&q=80&w=1200',
  'https://images.unsplash.com/photo-1541414779316-956a5084c0d4?auto=format&fit=crop&q=80&w=1200',
  'https://images.unsplash.com/photo-1584132967334-10e028bd69f7?auto=format&fit=crop&q=80&w=1200',
];

const FocusGallery: React.FC = () => {
  const [activeIdx, setActiveIdx] = useState(1);
  const [hoverIdx, setHoverIdx] = useState<number | null>(null);

  const handleSwap = (idx: number) => {
    if (idx === activeIdx) return;
    setActiveIdx(idx);
  };

  return (
    <section className="py-20 relative overflow-hidden leaf-pattern">
      <div className="container mx-auto px-6 max-w-7xl relative z-10">
        <div className="flex flex-col md:flex-row items-center justify-center gap-4 md:gap-8 h-[500px] md:h-[700px]">
          {IMAGES.map((src, idx) => {
            const isActive = idx === activeIdx;
            const isLeft = (activeIdx === 0 && idx === 1) || (activeIdx === 1 && idx === 0) || (activeIdx === 2 && idx === 0);
            
            // Layout logic: 
            // 0 is active -> [0, 1, 2]
            // 1 is active -> [0, 1, 2]
            // 2 is active -> [0, 1, 2]
            // We just render them in order but scale the active one.
            
            return (
              <div 
                key={idx}
                onClick={() => handleSwap(idx)}
                onMouseEnter={() => !isActive && setHoverIdx(idx)}
                onMouseLeave={() => setHoverIdx(null)}
                className={`relative transition-all duration-1000 ease-in-out cursor-pointer overflow-hidden shadow-2xl rounded-sm
                  ${isActive ? 'w-full md:w-[50%] h-[100%] z-20' : 'w-full md:w-[25%] h-[70%] md:h-[85%] z-10'}
                `}
              >
                {/* Image Layer */}
                <img 
                  src={src} 
                  alt={`Safari Focus ${idx}`} 
                  className={`w-full h-full object-cover transition-all duration-1000 
                    ${isActive ? 'grayscale-0 scale-100' : 'grayscale group-hover:grayscale-0 scale-110'}
                  `}
                />

                {/* Overlay for inactive */}
                {!isActive && (
                  <div className="absolute inset-0 bg-black/20 group-hover:bg-black/0 transition-all duration-500"></div>
                )}

                {/* Hover Arrow Animation */}
                {!isActive && hoverIdx === idx && (
                  <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                    <div className="w-20 h-20 rounded-full border border-white/50 flex items-center justify-center animate-pulse bg-white/10 backdrop-blur-sm">
                      <i className={`fa-solid ${idx < activeIdx ? 'fa-arrow-right' : 'fa-arrow-left'} text-white text-2xl`}></i>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
};

export default FocusGallery;
