
"use client";

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { TourPreferences, TourItinerary, AppSection } from '../types';
import { planTour } from '../app/actions';

const TourPlanner: React.FC = () => {
  const [step, setStep] = useState(1);
  const [preferences, setPreferences] = useState<TourPreferences>({
    duration: 3,
    interests: [],
    budget: 'mid-range',
    groupSize: 2,
    specialRequests: ''
  });
  const [itinerary, setItinerary] = useState<TourItinerary | null>(null);
  const [isPlanning, setIsPlanning] = useState(false);

  const interestsOptions = [
    'Leopard Tracking',
    'Bird Watching',
    'Photography',
    'Night Safaris',
    'Cultural Heritage',
    'Luxury Camping',
    'Nature Walks',
    'Wildlife Conservation'
  ];

  const handleInterestToggle = (interest: string) => {
    setPreferences(prev => ({
      ...prev,
      interests: prev.interests.includes(interest)
        ? prev.interests.filter(i => i !== interest)
        : [...prev.interests, interest]
    }));
  };

  const startPlanning = async () => {
    setIsPlanning(true);
    try {
      const result = await planTour(preferences);
      setItinerary(result);
      setStep(4);
    } catch (error) {
      console.error("Planning failed:", error);
    } finally {
      setIsPlanning(false);
    }
  };

  return (
    <div className="min-h-screen pt-32 pb-20 px-6 bg-[#022C22] leaf-pattern">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-16">
          <motion.h2 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-4xl md:text-6xl font-serif mb-4"
          >
            AI Tour Planner
          </motion.h2>
          <motion.p 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="text-emerald-400/80 tracking-[0.2em] uppercase text-xs font-bold"
          >
            Crafting your perfect wilderness escape
          </motion.p>
        </div>

        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-8 md:p-12 shadow-2xl">
          <AnimatePresence mode="wait">
            {step === 1 && (
              <motion.div 
                key="step1"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-8"
              >
                <div className="space-y-4">
                  <label className="block text-sm font-bold tracking-widest uppercase opacity-60">How many days?</label>
                  <div className="flex items-center gap-6">
                    <button 
                      onClick={() => setPreferences(p => ({ ...p, duration: Math.max(1, p.duration - 1) }))}
                      className="w-12 h-12 rounded-full border border-white/20 flex items-center justify-center hover:bg-emerald-600 transition-colors"
                    >-</button>
                    <span className="text-4xl font-serif w-12 text-center">{preferences.duration}</span>
                    <button 
                      onClick={() => setPreferences(p => ({ ...p, duration: Math.min(14, p.duration + 1) }))}
                      className="w-12 h-12 rounded-full border border-white/20 flex items-center justify-center hover:bg-emerald-600 transition-colors"
                    >+</button>
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="block text-sm font-bold tracking-widest uppercase opacity-60">Group Size</label>
                  <input 
                    type="range" 
                    min="1" 
                    max="12" 
                    value={preferences.groupSize}
                    onChange={(e) => setPreferences(p => ({ ...p, groupSize: parseInt(e.target.value) }))}
                    className="w-full h-2 bg-emerald-900 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                  />
                  <div className="flex justify-between text-xs opacity-50">
                    <span>1 Person</span>
                    <span>{preferences.groupSize} People</span>
                    <span>12 People</span>
                  </div>
                </div>

                <button 
                  onClick={() => setStep(2)}
                  className="w-full bg-emerald-600 py-5 rounded-xl font-bold tracking-widest uppercase hover:bg-emerald-500 transition-all shadow-xl"
                >
                  Continue
                </button>
              </motion.div>
            )}

            {step === 2 && (
              <motion.div 
                key="step2"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-8"
              >
                <div className="space-y-4">
                  <label className="block text-sm font-bold tracking-widest uppercase opacity-60">What interests you?</label>
                  <div className="grid grid-cols-2 gap-3">
                    {interestsOptions.map(interest => (
                      <button
                        key={interest}
                        onClick={() => handleInterestToggle(interest)}
                        className={`px-4 py-3 rounded-xl text-[10px] font-bold tracking-widest uppercase border transition-all ${
                          preferences.interests.includes(interest)
                            ? 'bg-emerald-600 border-emerald-400 text-white'
                            : 'bg-white/5 border-white/10 text-white/60 hover:border-white/30'
                        }`}
                      >
                        {interest}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="flex gap-4">
                  <button 
                    onClick={() => setStep(1)}
                    className="flex-1 border border-white/20 py-5 rounded-xl font-bold tracking-widest uppercase hover:bg-white/10 transition-all"
                  >
                    Back
                  </button>
                  <button 
                    onClick={() => setStep(3)}
                    className="flex-1 bg-emerald-600 py-5 rounded-xl font-bold tracking-widest uppercase hover:bg-emerald-500 transition-all shadow-xl"
                  >
                    Continue
                  </button>
                </div>
              </motion.div>
            )}

            {step === 3 && (
              <motion.div 
                key="step3"
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-8"
              >
                <div className="space-y-4">
                  <label className="block text-sm font-bold tracking-widest uppercase opacity-60">Budget Level</label>
                  <div className="grid grid-cols-3 gap-4">
                    {(['budget', 'mid-range', 'luxury'] as const).map(b => (
                      <button
                        key={b}
                        onClick={() => setPreferences(p => ({ ...p, budget: b }))}
                        className={`py-4 rounded-xl text-[10px] font-bold tracking-widest uppercase border transition-all ${
                          preferences.budget === b
                            ? 'bg-emerald-600 border-emerald-400 text-white'
                            : 'bg-white/5 border-white/10 text-white/60 hover:border-white/30'
                        }`}
                      >
                        {b}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="block text-sm font-bold tracking-widest uppercase opacity-60">Special Requests</label>
                  <textarea 
                    value={preferences.specialRequests}
                    onChange={(e) => setPreferences(p => ({ ...p, specialRequests: e.target.value }))}
                    placeholder="Any dietary requirements, accessibility needs, or specific animals you want to see?"
                    className="w-full bg-white/5 border border-white/10 rounded-xl p-4 text-sm outline-none focus:border-emerald-500 transition-colors h-32 resize-none"
                  />
                </div>

                <div className="flex gap-4">
                  <button 
                    onClick={() => setStep(2)}
                    className="flex-1 border border-white/20 py-5 rounded-xl font-bold tracking-widest uppercase hover:bg-white/10 transition-all"
                  >
                    Back
                  </button>
                  <button 
                    onClick={startPlanning}
                    disabled={isPlanning}
                    className="flex-1 bg-emerald-600 py-5 rounded-xl font-bold tracking-widest uppercase hover:bg-emerald-500 transition-all shadow-xl flex items-center justify-center gap-3"
                  >
                    {isPlanning ? (
                      <>
                        <i className="fa-solid fa-circle-notch animate-spin"></i>
                        Planning...
                      </>
                    ) : 'Generate Itinerary'}
                  </button>
                </div>
              </motion.div>
            )}

            {step === 4 && itinerary && (
              <motion.div 
                key="step4"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                className="space-y-12"
              >
                <div className="text-center border-b border-white/10 pb-8">
                  <h3 className="text-3xl font-serif mb-4">{itinerary.title}</h3>
                  <p className="text-sm opacity-70 leading-relaxed">{itinerary.summary}</p>
                </div>

                <div className="space-y-16">
                  {itinerary.days.map((day, idx) => (
                    <div key={idx} className="relative pl-8 border-l border-emerald-500/30">
                      <div className="absolute -left-[9px] top-0 w-4 h-4 rounded-full bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.5)]"></div>
                      <div className="mb-6">
                        <span className="text-emerald-400 text-[10px] font-bold tracking-[0.3em] uppercase">Day {day.day}</span>
                        <h4 className="text-2xl font-serif mt-1">{day.title}</h4>
                      </div>

                      <div className="space-y-6">
                        {day.activities.map((act, aidx) => (
                          <div key={aidx} className="flex gap-6">
                            <div className="w-20 shrink-0 text-[10px] font-bold tracking-widest uppercase opacity-40 pt-1">
                              {act.time}
                            </div>
                            <div className="space-y-1">
                              <h5 className="font-bold text-sm">{act.activity}</h5>
                              <p className="text-xs opacity-60 leading-relaxed">{act.description}</p>
                            </div>
                          </div>
                        ))}
                      </div>

                      <div className="mt-8 grid grid-cols-2 gap-8 pt-8 border-t border-white/5">
                        <div>
                          <span className="text-[10px] font-bold tracking-widest uppercase opacity-40 block mb-3">Meals</span>
                          <div className="flex flex-wrap gap-2">
                            {day.meals.map(m => (
                              <span key={m} className="px-3 py-1 bg-emerald-900/40 rounded-full text-[9px] font-bold uppercase tracking-wider">{m}</span>
                            ))}
                          </div>
                        </div>
                        <div>
                          <span className="text-[10px] font-bold tracking-widest uppercase opacity-40 block mb-3">Stay</span>
                          <p className="text-xs font-bold">{day.accommodation}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>

                {itinerary.totalEstimatedPrice && (
                  <div className="bg-emerald-900/20 rounded-2xl p-6 text-center border border-emerald-500/20">
                    <span className="text-[10px] font-bold tracking-widest uppercase opacity-60 block mb-2">Estimated Investment</span>
                    <p className="text-3xl font-serif text-emerald-400">{itinerary.totalEstimatedPrice}</p>
                  </div>
                )}

                <div className="flex gap-4">
                  <button 
                    onClick={() => setStep(1)}
                    className="flex-1 border border-white/20 py-5 rounded-xl font-bold tracking-widest uppercase hover:bg-white/10 transition-all"
                  >
                    Plan Another
                  </button>
                  <button 
                    className="flex-1 bg-emerald-600 py-5 rounded-xl font-bold tracking-widest uppercase hover:bg-emerald-500 transition-all shadow-xl"
                  >
                    Book This Trip
                  </button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
};

export default TourPlanner;
