'use client';

import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import Hero from '../components/Hero';
import Preloader from '../components/Preloader';
import AvailabilityBar from '../components/AvailabilityBar';
import About from '../components/About';
import Accommodation from '../components/Accommodation';
import FoodAndDrinks from '../components/FoodAndDrinks';
import Experiences from '../components/Experiences';
import BookingSelection from '../components/BookingSelection';
import Checkout from '../components/Checkout';
import TourPlanner from '../components/TourPlanner';
import Footer from '../components/Footer';
import BeastAnimation from '../components/BeastAnimation';
import ScrollingGallery from '../components/ScrollingGallery';
import FocusGallery from '../components/FocusGallery';
import Chatbot from '../components/Chatbot';
import Blog from '../components/Blog';
import ContactUs from '../components/ContactUs';

// Section components
import HomeWelcome from '../components/HomeWelcome';
import ServiceGrid from '../components/ServiceGrid';
import Testimonial from '../components/Testimonial';
import ThingsToKnow from '../components/ThingsToKnow';

import { AppSection, SelectedRoom } from '../types';

const Home: React.FC = () => {
  const [activeSection, setActiveSection] = useState<AppSection>(AppSection.HOME);
  const [isLoading, setIsLoading] = useState(true);
  const [isChatOpen, setIsChatOpen] = useState(false);
  
  // Requirement: No dates shown on initial load
  const [bookingParams, setBookingParams] = useState({
    checkIn: '',
    checkOut: '',
    adults: 1,
    children: 0
  });

  const [selectedRooms, setSelectedRooms] = useState<SelectedRoom[]>([]);

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 2500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [activeSection]);

  if (isLoading) {
    return <Preloader />;
  }

  const handleAvailabilityCheck = (checkIn: string, checkOut: string, adults: number, children: number) => {
    setBookingParams({ checkIn, checkOut, adults, children });
    setActiveSection(AppSection.BOOKING);
  };

  const handleProceedToCheckout = (rooms: SelectedRoom[]) => {
    setSelectedRooms(rooms);
    setActiveSection(AppSection.CHECKOUT);
  };

  return (
    <div className="min-h-screen bg-[#022C22] text-white overflow-x-hidden relative">
      <BeastAnimation />
      <Navbar activeSection={activeSection} setActiveSection={setActiveSection} />
      
      {activeSection === AppSection.ABOUT && <About />}
      {activeSection === AppSection.ACCOMMODATION && <Accommodation />}
      {activeSection === AppSection.FOOD_AND_DRINKS && <FoodAndDrinks />}
      {activeSection === AppSection.EXPERIENCES && <Experiences />}
      {activeSection === AppSection.TOUR_PLANNER && <TourPlanner />}
      {activeSection === AppSection.BLOG && <Blog />}
      {activeSection === AppSection.CONTACT_US && <ContactUs />}
      {activeSection === AppSection.BOOKING && (
        <BookingSelection 
          checkIn={bookingParams.checkIn} 
          checkOut={bookingParams.checkOut} 
          adults={bookingParams.adults} 
          childrenCount={bookingParams.children}
          onUpdateParams={handleAvailabilityCheck}
          onProceed={handleProceedToCheckout}
        />
      )}
      {activeSection === AppSection.CHECKOUT && (
        <Checkout 
          checkIn={bookingParams.checkIn} 
          checkOut={bookingParams.checkOut} 
          adults={bookingParams.adults} 
          childrenCount={bookingParams.children}
          rooms={selectedRooms}
          onBack={() => setActiveSection(AppSection.BOOKING)}
        />
      )}

      {activeSection === AppSection.HOME && (
        <>
          <Hero onStart={setActiveSection} />
          <AvailabilityBar 
            initialCheckIn={bookingParams.checkIn}
            initialCheckOut={bookingParams.checkOut}
            initialAdults={bookingParams.adults}
            initialChildren={bookingParams.children}
            onCheck={handleAvailabilityCheck} 
          />

          <HomeWelcome />

          {/* Section with the targeted jungle image strip */}
          <div className="relative bg-white overflow-hidden">
            {/* 
              The Jungle Image Strip 
              Positioned to span across the bottom of ServiceGrid and top of FocusGallery.
              Increased height and opacity for clear visibility.
            */}
            <div className="absolute top-1/2 left-0 w-full h-[1000px] -translate-y-1/2 z-0 opacity-90 pointer-events-none">
              <img 
                src="/leafbackground.jpg" 
                className="w-full h-full object-cover"
                alt="Jungle Strip"
                onError={(e) => {
                  // Fallback if image isn't found yet
                  e.currentTarget.style.backgroundColor = '#064E3B';
                  e.currentTarget.style.opacity = '0.2';
                }}
              />
              <div className="absolute inset-0 bg-gradient-to-b from-white via-transparent to-white"></div>
            </div>

            <div className="relative z-10">
              <ServiceGrid />
              <FocusGallery />
            </div>
          </div>

          <Testimonial />
          <ThingsToKnow />
          <ScrollingGallery />
        </>
      )}


      <Footer setActiveSection={setActiveSection} />

      <Chatbot isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} />

      {/* Floating Buttons */}
      <div className="fixed bottom-10 right-10 flex flex-col gap-6 z-[200]">
        <div onClick={() => setIsChatOpen(!isChatOpen)} className="w-14 h-14 bg-emerald-600 rounded-full flex items-center justify-center text-white text-xl shadow-2xl hover:scale-110 cursor-pointer border-2 border-white group">
            <i className="fa-solid fa-sparkles"></i>
            <span className="absolute right-full mr-4 bg-emerald-700 text-white text-[10px] font-bold py-2 px-4 rounded-full opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap shadow-xl">AI GUIDE</span>
        </div>
        <a href="https://wa.me/94770083313" target="_blank" rel="noreferrer" className="w-14 h-14 bg-[#25D366] rounded-full flex items-center justify-center text-white text-3xl shadow-2xl hover:scale-110 border-2 border-white">
          <i className="fa-brands fa-whatsapp"></i>
        </a>
      </div>
    </div>
  );
};

export default Home;
